using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using Object=UnityEngine.Object;
public static class ValidateShopCorrections {
 public static string Edit(){var root=GameObject.Find("New_Map").transform;var shop=root.Find("11_Five_Hangar_Farm/S - Farm supplies and cottage/Farm supplies shop");var tools=shop.Find("Individual editable tools");var report=new List<string>();report.Add((tools.childCount==11?"PASS ":"FAIL ")+"11 separate editable tool objects");var meshes=tools.Cast<Transform>().Select(t=>t.GetComponent<MeshFilter>().sharedMesh).ToArray();report.Add((meshes.Distinct().Count()==11?"PASS ":"FAIL ")+"Each tool has its own mesh asset");foreach(var t in tools.Cast<Transform>().Where(t=>t.name.StartsWith("Counter -"))){var points=t.GetComponent<MeshFilter>().sharedMesh.vertices.Select(v=>shop.InverseTransformPoint(t.TransformPoint(v))).ToArray();float min=points.Min(v=>v.y),max=points.Max(v=>v.y);report.Add((Mathf.Abs(min-1.151f)<.002f&&max-min<.14f?"PASS ":"FAIL ")+t.name+" tabletop contact="+min.ToString("F4")+"m; thickness="+(max-min).ToString("F4")+"m");}var front=shop.Find("Solid upper facade and sign supports");report.Add((front&&front.GetComponent<MeshFilter>().sharedMesh&&front.GetComponent<Renderer>().bounds.size.y>3?"PASS ":"FAIL ")+"Solid framed facade extends from canopy to roof ridge");var result=string.Join("\n",report);File.WriteAllText("output/NewMap/ShopCorrections/tool-validation.txt",result);return result;}
 public static string Walk(){if(!Application.isPlaying)throw new Exception("Play mode required");var terrain=GameObject.Find("New_Map").GetComponentInChildren<Terrain>();var road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),0,float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();float[] lengths=new float[road.Length];for(int i=1;i<road.Length;i++)lengths[i]=lengths[i-1]+Vector3.Distance(road[i],road[i-1]);Func<float,Vector3> at=s=>{int i=Array.FindIndex(lengths,v=>v>=s);i=Mathf.Clamp(i,1,road.Length-1);return Vector3.Lerp(road[i-1],road[i],Mathf.InverseLerp(lengths[i-1],lengths[i],s));};var go=new GameObject("Temporary road transition walker");var cc=go.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.3f;cc.center=new Vector3(0,.9f,0);cc.skinWidth=.025f;float maxError=0;int steps=0;try{cc.enabled=false;var start=at(18);start.y=terrain.SampleHeight(start)+terrain.transform.position.y+.06f;go.transform.position=start;cc.enabled=true;Physics.SyncTransforms();for(float s=18.5f;s<=100;s+=.5f){var p=at(s);var d=p-go.transform.position;d.y=-.25f;cc.Move(d);maxError=Mathf.Max(maxError,Vector2.Distance(new Vector2(p.x,p.z),new Vector2(go.transform.position.x,go.transform.position.z)));steps++;}}finally{Object.DestroyImmediate(go);}string result=(maxError<.2f?"PASS ":"FAIL ")+"CharacterController walked 82m yard/road transition in "+steps+" half-metre steps; max horizontal obstruction error="+maxError.ToString("F4")+"m.";File.WriteAllText("output/NewMap/ShopCorrections/walk-validation.txt",result);return result;}
}
